{"path": "poker.py", "content": "from collections import Counter

RANKS = {r: i for i, r in enumerate("23456789", 2)}
RANKS.update({"10": 10, "J": 11, "Q": 12, "K": 13, "A": 14})


def _score(hand):
    cards = hand.split() if isinstance(hand, str) else list(hand)
    values = [RANKS[c[:-1]] for c in cards]
    suits = {c[-1] for c in cards}
    counts = Counter(values)
    # order by count then value
    groups = sorted(counts.items(), key=lambda kv: (kv[1], kv[0]), reverse=True)
    ordered = [v for v, _ in groups]
    shape = [n for _, n in groups]
    flush = len(suits) == 1
    straight = False
    if len(counts) == 5:
        if max(values) - min(values) == 4:
            straight = True
        elif set(values) == {14, 2, 3, 4, 5}:
            straight = True
            ordered = [5, 4, 3, 2, 1]
    if straight and flush:
        cat = 8
    elif shape == [4, 1]:
        cat = 7
    elif shape == [3, 2]:
        cat = 6
    elif flush:
        cat = 5
    elif straight:
        cat = 4
    elif shape == [3, 1, 1]:
        cat = 3
    elif shape == [2, 2, 1]:
        cat = 2
    elif shape == [2, 1, 1, 1]:
        cat = 1
    else:
        cat = 0
    return (cat, ordered)


def best_hands(hands):
    scores = [_score(h) for h in hands]
    top = max(scores)
    return [h for h, s in zip(hands, scores) if s == top]
